import { useEffect, useRef, useState } from 'react'
import { login, signup, startGoogleLogin, type Session } from '../lib/session'
import { Dialog, DialogClose, DialogContent, DialogDescription, DialogTitle } from './ui/dialog'
import { FolioWordmark } from './FolioWordmark'
import { AppIcon } from './AppIcon'

const messages:Record<string,string>={
  signup_disabled:'회원가입이 현재 중지되어 있습니다. 잠시 후 다시 시도하세요.',
  email_provider_disabled:'이메일 가입이 현재 중지되어 있습니다.',
  email_address_invalid:'올바른 이메일 주소를 입력하세요.',
  weak_password:'더 안전한 비밀번호를 사용하세요.',
  user_already_exists:'이미 가입된 이메일입니다. 로그인해주세요.',
  over_email_send_rate_limit:'확인 메일 요청이 많습니다. 잠시 후 다시 시도하세요.',
  over_request_rate_limit:'요청이 많습니다. 잠시 후 다시 시도하세요.',
  signup_failed:'회원가입을 완료하지 못했습니다. 잠시 후 다시 시도하세요.',
  email_not_confirmed:'가입 확인 메일의 링크를 누른 뒤 로그인하세요.',
  email_confirmation_failed:'이메일 확인 링크가 만료됐거나 유효하지 않습니다. 가입 메일을 다시 확인하세요.',
  email_confirmed:'이메일 확인이 완료되었습니다. 로그인해주세요.',
  login_failed:'이메일 또는 비밀번호를 확인하세요.',
  email_and_password_required:'이메일과 8자 이상의 비밀번호를 입력하세요.',
  oauth_failed:'Google 로그인을 확인하지 못했습니다. 다시 시도하세요.',
  oauth_state_missing:'로그인을 시작한 창과 다른 곳에서 돌아왔습니다. 다시 시도하세요.',
  oauth_access_denied:'Google 로그인이 취소되었습니다.',
  google_provider_disabled:'Google 로그인 연결 설정이 아직 완료되지 않았습니다. 이메일로 로그인할 수 있습니다.',
  google_unavailable:'Google 로그인 연결을 확인하지 못했습니다. 잠시 후 다시 시도하거나 이메일로 로그인하세요.',
  auth_provider_check_failed:'Google 로그인 연결을 확인하지 못했습니다. 잠시 후 다시 시도하거나 이메일로 로그인하세요.'
}

export function AuthModal({
  open,
  onClose,
  onAuthenticated,
  notice
}:{
  open:boolean
  onClose:()=>void
  onAuthenticated:(session:Session)=>void
  notice?:string
}){
  const [mode,setMode]=useState<'login'|'signup'>('login')
  const [email,setEmail]=useState('')
  const [password,setPassword]=useState('')
  const [info,setInfo]=useState('')
  const [busy,setBusy]=useState(false)
  const [error,setError]=useState('')
  const pending=useRef<AbortController|null>(null)
  useEffect(()=>{if(!open){pending.current?.abort();setBusy(false)}return()=>pending.current?.abort()},[open])
  useEffect(()=>{if(notice==='email_confirmed'){setInfo(messages.email_confirmed);setError('')}else if(notice)setError(messages[notice]||'로그인을 확인하지 못했습니다: '+notice)},[notice])
  const google=async()=>{pending.current?.abort();const attempt=new AbortController();pending.current=attempt;setBusy(true);setError('');try{await startGoogleLogin(attempt.signal)}catch(e){if(!attempt.signal.aborted){setBusy(false);setError(messages[e instanceof Error?e.message:'']||messages.google_unavailable)}}}

  const submit=async()=>{
    pending.current?.abort();const attempt=new AbortController();pending.current=attempt
    setBusy(true);setError('');setInfo('')
    try{
      const session=mode==='login'
        ? await login(email,password,attempt.signal)
        : await signup(email,password,attempt.signal)
      if(attempt.signal.aborted)return
      if(!session){setInfo('가입 확인 메일을 확인해주세요. 이메일의 링크를 누른 뒤 로그인할 수 있습니다.');setMode('login');setPassword('');return}
      onAuthenticated(session)
      onClose()
    }catch(e){
      if(attempt.signal.aborted||(e instanceof Error&&e.message==='auth_cancelled'))return
      const code=e instanceof Error?e.message:String(e)
      setError(messages[code]||'인증에 실패했습니다: '+code)
    }finally{if(pending.current===attempt)setBusy(false)}
  }

  return <Dialog open={open} onOpenChange={next=>{if(!next)onClose()}}>
    <DialogContent className="auth-card">
      <div className="auth-head">
        <div><FolioWordmark className="auth-wordmark"/><DialogTitle>{mode==='login'?'로그인':'회원가입'}</DialogTitle></div>
        <DialogClose asChild><button aria-label="닫기"><AppIcon name="close"/></button></DialogClose>
      </div>
      {mode==='login'&&<><button type="button" className="auth-google" disabled={busy} onClick={google}><svg aria-hidden="true" viewBox="0 0 18 18" width="18" height="18"><path fill="#4285F4" d="M17.64 9.2c0-.64-.06-1.25-.16-1.84H9v3.48h4.84a4.14 4.14 0 0 1-1.8 2.72v2.26h2.92c1.7-1.57 2.68-3.88 2.68-6.62z"/><path fill="#34A853" d="M9 18c2.43 0 4.47-.8 5.96-2.18l-2.92-2.26c-.8.54-1.84.86-3.04.86-2.34 0-4.32-1.58-5.03-3.7H.96v2.33A9 9 0 0 0 9 18z"/><path fill="#FBBC05" d="M3.97 10.72A5.4 5.4 0 0 1 3.68 9c0-.6.1-1.18.29-1.72V4.95H.96A9 9 0 0 0 0 9c0 1.45.35 2.83.96 4.05l3.01-2.33z"/><path fill="#EA4335" d="M9 3.58c1.32 0 2.5.45 3.44 1.35l2.58-2.58A9 9 0 0 0 .96 4.95l3.01 2.33C4.68 5.16 6.66 3.58 9 3.58z"/></svg>Google 계정으로 로그인</button>
      <div className="auth-or"><span>또는 이메일</span></div></>}
      <div className="auth-tabs">
        <button className={mode==='login'?'on':''} onClick={()=>{setMode('login');setError('');setInfo('')}}>로그인</button>
        <button className={mode==='signup'?'on':''} onClick={()=>{setMode('signup');setError('');setInfo('')}}>회원가입</button>
      </div>
      <label>이메일<input type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} /></label>
      <label>비밀번호<input type="password" autoComplete={mode==='login'?'current-password':'new-password'} value={password} onChange={e=>setPassword(e.target.value)} /></label>
      {info&&<p className="auth-info" role="status">{info}</p>}
      {error&&<div className="auth-error">{error}</div>}
      <button className="auth-submit" disabled={busy||!email||password.length<8} onClick={submit}>{busy?'처리 중…':mode==='login'?'로그인':'가입하기'}</button>
      <DialogDescription className="auth-description">관심·보유종목과 투자 기록은 내 계정에 저장됩니다. 사진·손글씨 저널은 이 기기에 계정별로 저장됩니다.</DialogDescription>
    </DialogContent>
  </Dialog>
}
