import {AppIcon} from './AppIcon'
import {useState} from 'react'
import type {LeaderRow} from '../types'
import {usePriceHistory} from '../lib/priceHistory'
import {useLiveQuotes} from '../lib/liveQuotes'
const pct=(v:number|null|undefined)=>v==null||!Number.isFinite(v)?'—':(v>=0?'+':'')+(v*100).toFixed(1)+'%'
import {miniTrend} from '../lib/miniTrend'
export function StockTrendList({rows,onSelect,getClass,onAddToBasket,isInBasket,className='',view='cards',emptyLabel='선택한 범위와 필터에 맞는 종목이 없습니다.'}:{rows:LeaderRow[];onSelect:(row:LeaderRow)=>void;getClass:(row:LeaderRow)=>string;onAddToBasket?:(row:LeaderRow)=>void;isInBasket?:(row:LeaderRow)=>boolean;className?:string;view?:'cards'|'list';emptyLabel?:string}){
 const [limit,setLimit]=useState(20)
 const shown=rows.slice(0,limit)
 const hist=usePriceHistory(shown.map(r=>r.id),view==='cards'&&shown.length>0)
 const liveQuote=useLiveQuotes(shown,view==='list'?shown.length:0)

 if(view==='list')return <><div className={'stock-compact-list '+className} role="list" aria-label="분석 종목 목록">
  <div className="stock-compact-head" aria-hidden="true"><span>종목명</span><span>Ticker</span><span>현재가</span><span>등락률</span><span>RS순위</span><span/></div>
  {shown.map(row=>{
    const quote=liveQuote(row)
    const current=quote!=null&&Number.isFinite(quote.price)&&quote.price>0?quote.price:row.price
    const price=current==null||!Number.isFinite(current)?'—':(row.market==='US'?'$':'₩')+new Intl.NumberFormat(row.market==='US'?'en-US':'ko-KR',{minimumFractionDigits:row.market==='US'?2:0,maximumFractionDigits:row.market==='US'?2:0}).format(current)
    const dayReturn=quote&&quote.previous_close!=null&&Number.isFinite(quote.previous_close)&&quote.previous_close>0&&Number.isFinite(quote.price)?quote.price/quote.previous_close-1:null
    const change=dayReturn??row.return_20d
    const tone=change!=null&&Number.isFinite(change)?(change>0?'positive':change<0?'negative':''):''
    const changePeriod=dayReturn==null?'20D':'1D'
    return <div key={row.market+'|'+row.ticker} className="stock-compact-row" role="listitem" data-market={row.market}>
      <button className="stock-compact-main" type="button" onClick={()=>onSelect(row)} aria-label={row.name+' '+row.ticker+' 현재가 '+price+' '+changePeriod+' 등락률 '+pct(change)+' RS '+(row.rs_rank==null?'정보 없음':Math.round(row.rs_rank))+' 종목 상세 보기'}>
        <strong title={row.name||row.ticker}>{row.name||row.ticker}</strong><span className="stock-compact-ticker" title={row.ticker}>{row.ticker}</span><span className={'stock-compact-price '+tone}>{price}</span><span className={'stock-compact-change '+tone}><small>{changePeriod}</small>{pct(change)}</span><span className="stock-compact-rs">{row.rs_rank==null?'—':Math.round(row.rs_rank)}</span>
      </button>{onAddToBasket&&<button type="button" className="stock-compact-basket" aria-label={row.ticker+' '+(isInBasket?.(row)?'장바구니 담김':'장바구니 담기')} aria-pressed={!!isInBasket?.(row)} onClick={()=>onAddToBasket(row)}><AppIcon name="basket"/></button>}
    </div>
  })}
  {!rows.length&&<p className="empty">{emptyLabel}</p>}
 </div>{limit<rows.length&&<button type="button" className="secondary-action stock-trend-more" onClick={()=>setLimit(n=>n+20)}>더 보기 · {Math.min(20,rows.length-limit)}종목</button>}</>
 return <><div className={'stock-trend-list decision-list '+className} role="list" aria-label="분석 종목 목록">{shown.map(row=>{
  const trend=miniTrend(hist.get(row.id))
  const change=row.return_20d
  const price=row.price==null?'—':new Intl.NumberFormat(row.market==='US'?'en-US':'ko-KR',{minimumFractionDigits:row.market==='US'?2:0,maximumFractionDigits:row.market==='US'?2:0}).format(row.price)
  const detail=<button key={row.id} data-market={row.market} type="button" role={onAddToBasket?undefined:'listitem'} className="stock-trend-row decision-row" aria-label={`${row.name||row.ticker} 종목 상세 보기`} onClick={()=>onSelect(row)}>
   <span className="stock-trend-copy decision-main"><b className={row.market==='KR'?'stock-trend-name':'stock-trend-ticker'} title={row.name||row.ticker}>{row.market==='KR'?(row.name||row.ticker):row.ticker}</b><small className={'decision-eyebrow '+(row.market==='KR'?'stock-trend-ticker':'stock-trend-name')} title={row.name||row.ticker}>{row.market==='KR'?row.ticker:(row.name||row.ticker)}</small><span className="stock-trend-tags"><i>{getClass(row)}</i><small>RS {row.rs_rank==null?'—':Math.round(row.rs_rank)}</small></span></span>
   <span className="stock-mini-trend">{trend?<><svg viewBox="0 0 100 48" role="img" aria-label={`${row.ticker} ${trend.complete?'20거래일':'확보된 기간'} 일간 종가 추세`} className={trend.up?'positive':'negative'}><title>{trend.start} ~ {trend.end} · 일간 종가{trend.complete?'':' · 20D 이력 부족'}</title><path className="trend-laser-depth" d={trend.path}/><path className="trend-laser-glow" d={trend.path}/><path className="trend-laser-beam" d={trend.path}/><path className="trend-laser-core" d={trend.path}/></svg><small>{trend.complete?'20D':'이력 부족'}</small></>:<span className="stock-trend-missing">{hist.status==='loading'?'이력 로딩':'이력 없음'}</span>}</span>
   <span className="stock-trend-price decision-value"><b className={(change??0)>0?'positive':(change??0)<0?'negative':''}>{row.market==='US'?'$':'₩'}{price}</b><small className={(change??0)>0?'positive':(change??0)<0?'negative':''}>20D {pct(change)}</small></span>
  </button>
  return onAddToBasket?<article key={row.id} role="listitem" className="stock-catalog-card" data-market={row.market}>{detail}<button type="button" className="stock-basket-add" aria-label={`${row.ticker} ${isInBasket?.(row)?'장바구니 담김':'장바구니 담기'}`} aria-pressed={!!isInBasket?.(row)} onClick={()=>onAddToBasket(row)}><AppIcon name="basket"/><span>{isInBasket?.(row)?'담김':'담기'}</span></button></article>:detail
 })}{!rows.length&&<p className="empty">{emptyLabel}</p>}</div>{limit<rows.length&&<button type="button" className="secondary-action stock-trend-more" onClick={()=>setLimit(n=>n+20)}>더 보기 · {Math.min(20,rows.length-limit)}종목</button>}</>
}
