const HEAT_THRESHOLDS:Record<EtfHeatPeriod,[number,number]>={'5D':[.01,.03],'20D':[.02,.06],'50D':[.03,.10],'120D':[.05,.15],'200D':[.07,.20],'52W':[.10,.30]}
const pctLabel=(v:number)=>`${v>0?'+':''}${Math.round(v*100)}%`
